//! Inkling 2 Mini's routed experts on XPU: the kernels of kernels/xpu/inkling2/experts.cl and their planted twins,
//! as gate 5 records them (generated by `tf-xpu-kernel-contract limits`, which prints each RECORD line).
const std = @import("std");
const limits = @import("xpu_limits.zig");

const X = limits.XpuLaunch;
const U = limits.XpuUsage;

const native = limits.Format.native;

fn rec(comptime R: type, comptime name: []const u8, comptime symbol: []const u8, comptime image: []const u8, comptime threads: u32, comptime usage: U) R {
    return .{
        .launch = .{ .name = name, .symbol = symbol, .image = image, .format = native, .threads = .{ threads, 1, 1 }, .slm = usage.slm, .sub_group = 16, .grf = 256 },
        .usage = .{usage},
    };
}

/// The launches as the caller's `Record` type holds them.
pub fn list(comptime R: type) [24]R {
    return .{
    rec(R, "xpu inkling2 experts tf_ink2_nvfp4_gu", "tf_ink2_nvfp4_gu", "contract_inkling2_experts", 64, .{ .threads = .{ 64, 1, 1 }, .slm = 256, .sub_group = 16, .grf = 256 }),
    rec(R, "xpu inkling2 experts tf_ink2_nvfp4_down", "tf_ink2_nvfp4_down", "contract_inkling2_experts", 48, .{ .threads = .{ 48, 1, 1 }, .slm = 192, .sub_group = 16, .grf = 256 }),
