    rec(R, "xpu inkling2 experts tf_ink2_nvfp4_quantize", "tf_ink2_nvfp4_quantize", "contract_inkling2_experts", 256, .{ .threads = .{ 256, 1, 1 }, .slm = 0, .sub_group = 16, .grf = 256 }),
